  lv_net_sum: ['마리', 'fish', '匹', '尾'],
  lv_net_empty: ['살림망이 비어 있어요. 낚은 물고기가 여기에 담겨요.', 'Your keepnet is empty. The fish you land go in here.', 'スカリは空です。釣った魚がここに入ります。', '鱼护是空的。钓到的鱼会放在这里。'],
  lv_sell: ['팔기', 'Sell', '売る', '卖出'], lv_sell_all: ['모두 팔기 +{p}P', 'Sell all +{p}P', 'すべて売る +{p}P', '全部卖出 +{p}P'],
  lv_free: ['놓아주기', 'Let go', '逃がす', '放生'], lv_free_sure: ['한 번 더 누르면 놓아줘요', 'Tap again to let it go', 'もう一度押すと逃がします', '再点一次即放生'],
